CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT, category_id INT NOT NULL, name VARCHAR(180) NOT NULL, description TEXT NOT NULL, price BIGINT UNSIGNED NOT NULL, image VARCHAR(500) NOT NULL DEFAULT '', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE RESTRICT, INDEX idx_products_category (category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO settings VALUES ('whatsapp', '9647770445030');
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, csrf VARCHAR(64) NOT NULL, expires_at DATETIME NOT NULL, INDEX idx_session_expiry (expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders (id INT PRIMARY KEY AUTO_INCREMENT, reference VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, phone VARCHAR(20) NOT NULL, city VARCHAR(120) NOT NULL, address VARCHAR(500) NOT NULL, notes VARCHAR(500) NOT NULL DEFAULT '', total BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, product_id INT NULL, name VARCHAR(180) NOT NULL, image VARCHAR(500) NOT NULL, price BIGINT UNSIGNED NOT NULL, qty INT UNSIGNED NOT NULL, FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rate_limits (bucket VARCHAR(120) PRIMARY KEY, attempts INT NOT NULL, resets_at BIGINT NOT NULL, INDEX idx_rate_reset (resets_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
